def process_variable(base_variables, *args, **kwargs):
    # Evaluate base variable at initial time
    base_var = base_variables[0]
    base_eval_shape = base_var.shape
    base_eval_size = base_var.size

    # If clearly 0D/time-only (no spatial dimension), return 0D early
    if len(base_eval_shape) == 0 or base_eval_shape[0] == 1:
        return ProcessedVariable0D(base_variables, *args, **kwargs)

    # Try to find a mesh/domain safely from the expression tree
    mesh = getattr(base_var, "mesh", None)
    domain = getattr(base_var, "domain", [])
    secondary_mesh = getattr(base_var, "secondary_mesh", None)

    if mesh is None or (isinstance(domain, list) and len(domain) == 0):
        # Traverse children to find any node with mesh/domain information
        try:
            for node in base_var.pre_order():
                if mesh is None and hasattr(node, "mesh") and node.mesh is not None:
                    mesh = node.mesh
                    domain = getattr(node, "domain", domain)
                if secondary_mesh is None and hasattr(node, "secondary_mesh"):
                    if node.secondary_mesh is not None:
                        secondary_mesh = node.secondary_mesh
                # break early if we have what we need
                if mesh is not None and (secondary_mesh is not None or base_eval_size):
                    pass
        except Exception:
            # If pre_order not available or something unexpected, keep best-effort values
            pass

    # handle 2D (in space) finite element variables differently
    if (
        mesh is not None
        and "current collector" in (domain or [])
        and isinstance(mesh, pybamm.ScikitSubMesh2D)
    ):
        return ProcessedVariable2DSciKitFEM(base_variables, *args, **kwargs)

    # If we still don't have a mesh, conservatively treat as 0D
    if mesh is None:
        return ProcessedVariable0D(base_variables, *args, **kwargs)

    # check for 1D variables based on mesh size
    n = mesh.npts
    base_shape = base_eval_shape[0]
    if base_shape in [n, n + 1]:
        return ProcessedVariable1D(base_variables, *args, **kwargs)

    # Try some shapes that could make the variable a 2D variable
    first_dim_nodes = mesh.nodes
    first_dim_edges = mesh.edges
    if secondary_mesh is None:
        # attempt traversal if not already found
        try:
            for node in base_var.pre_order():
                if hasattr(node, "secondary_mesh") and node.secondary_mesh is not None:
                    secondary_mesh = node.secondary_mesh
                    break
        except Exception:
            pass

    if secondary_mesh is not None:
        second_dim_pts = secondary_mesh.nodes
        if base_eval_size // len(second_dim_pts) in [
            len(first_dim_nodes),
            len(first_dim_edges),
        ]:
            return ProcessedVariable2D(base_variables, *args, **kwargs)

    # Raise error for 3D variable
    raise NotImplementedError(
        f"Shape not recognized for {base_variables[0]}"
        + "(note processing of 3D variables is not yet implemented)"
    )

